-- Applied on the owner's yes, 6 Nov 2026. 82 archive division titles that named the wrong subject now carry the official name from the printed motion. Every old value is matched exactly; a different row count rolls back. final-82.csv lists them.
BEGIN READ WRITE;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';
CREATE TEMP TABLE _titles (external_id text, old_value text NOT NULL, new_value text NOT NULL) ON COMMIT DROP;
DO $fix$
DECLARE n integer;
BEGIN
  UPDATE public.historic_commons_divisions t SET title = f.new_value FROM _titles f WHERE t.external_id = f.external_id AND t.title = f.old_value;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 82 THEN RAISE EXCEPTION 'division titles: expected 82 rows, touched %', n; END IF;
END
$fix$;
COMMIT;
